class Solution:
    def valueAfterKSeconds(self, n: int, k: int) -> int:
        MOD = 10**9 + 7
        N = n + k
        fact = [1] * (N + 1)
        for i in range(1, N + 1):
            fact[i] = fact[i - 1] * i % MOD
        inv = lambda x: pow(x, MOD - 2, MOD)
        return fact[N - 1] * inv(fact[k]) % MOD * inv(fact[n - 1]) % MOD

