class Solution {
    public int valueAfterKSeconds(int n, int k) {
        final long MOD = 1_000_000_007L;
        long[] a = new long[n];
        Arrays.fill(a, 1);
        while (k-- > 0)
            for (int i = 1; i < n; i++)
                a[i] = (a[i] + a[i - 1]) % MOD;
        return (int) a[n - 1];
    }
}

